for(const v of variants)v.lastFive={seasons:v.series.slice(-5).map(r=>r.season),startingPct:mean(v.series.slice(-5).map(r=>r.startingPct)),qualityPct:mean(v.series.slice(-5).map(r=>r.qualityPct)),expenses:mean(v.series.slice(-5).map(r=>r.expenses)),countryGapPct:mean(v.tierSeries.filter(r=>r.season>0).slice(-5).map(r=>r.aRelativeToDPct))};
